Use a sliding window with a `Map` to track the last index where each character appeared.

```js
function longestUniqueSubstring(s) {
  let left = 0;           // start of current sliding window
  let bestStart = 0;
  let bestLength = 0;
  const lastSeen = new Map();

  for (let right = 0; right < s.length; right++) {
    const ch = s[right];
    const previousIndex = lastSeen.get(ch);

    // If ch is already inside the current window, move left past it
    if (previousIndex !== undefined && previousIndex >= left) {
      left = previousIndex + 1;
    }

    lastSeen.set(ch, right);

    const windowLength = right - left + 1;

    if (windowLength > bestLength) {
      bestLength = windowLength;
      bestStart = left;
    }
  }

  return s.slice(bestStart, bestStart + bestLength);
}

// Tests
function test(input, expected) {
  const actual = longestUniqueSubstring(input);

  if (actual !== expected) {
    throw new Error(`FAIL: "${input}" => "${actual}", expected "${expected}"`);
  }

  console.log(`PASS: "${input}" => "${actual}"`);
}

test("abcabcbb", "abc");
test("pwwkew", "wke");
```

Time complexity: **O(n)**  
Space complexity: **O(min(n, alphabet size))**
